import numpy as np,pandas as pd
from lmfit.models import LorentzianModel,LinearModel,GaussianModel
def fit(x,y,lo,hi,specs,model=LorentzianModel):
    m=(x>lo)&(x<hi);mod=LinearModel(prefix='b_');p=mod.make_params(b_slope=0,b_intercept=np.percentile(y[m],5))
    for n,c,w in specs:
        L=model(prefix=n+'_');mod+=L
        p.update(L.make_params(**{n+'_center':c,n+'_sigma':w,n+'_amplitude':np.ptp(y[m])*w*2}))
        p[n+'_sigma'].set(min=2,max=80);p[n+'_amplitude'].set(min=0);p[n+'_center'].set(min=c-25,max=c+25)
    r=mod.fit(y[m],p,x=x[m]);return r
def rep(r,names):
    out={}
    for k in names:
        P=r.params;s=P[k+'_sigma'].value;A=P[k+'_amplitude'].value
        out[k]=(P[k+'_center'].value,2*s,A/(np.pi*s),A,P[k+'_sigma'].stderr)
    return out
for i in range(1,5):
    d=pd.read_csv(f'spectrum_dose{i}.csv');x=d.shift_cm1.values;y=d.intensity.values
    print('dose',i)
    if i<4:
        r=fit(x,y,1250,1450,[('D',1350,8)]);o=rep(r,['D']);
        r2=fit(x,y,1500,1700,[('G',1582,7),('Dp',1620,6)]);o.update(rep(r2,['G','Dp']))
    else:
        r=fit(x,y,1200,1480,[('D',1350,30)]);o=rep(r,['D'])
        r2=fit(x,y,1480,1750,[('G',1590,25),('Dp',1620,10)]);o.update(rep(r2,['G','Dp']))
    r3=fit(x,y,2500,2900,[('T',2690,15)]);o.update(rep(r3,['T']))
    for k,v in o.items():print('  %s pos %.1f FWHM %.1f H %.0f A %.0f'%v[:4])
    D,G,Dp,T=o['D'],o['G'],o['Dp'],o['T']
    print('  ID/IG H %.2f  A %.2f ; ID/ID\' %.1f ; I2D/IG %.2f ; A2D/AG %.2f'%(D[2]/G[2],D[3]/G[3],D[2]/max(Dp[2],1e-9),T[2]/G[2],T[3]/G[3]))
    print('  noise rms', np.std(np.diff(y[(x>1800)&(x<2100)]))/1.414)
